<!--
 * 用户账号管理页面 — 展示用户列表，支持新增/编辑/删除、角色分配、重置密码及多条件检索
 *
 * @path apps\userinfo-web\src\views\system\user\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 用户（列表页）
 * <p>用户账号（{@code ydsz_user}）的列表页，消费后端契约 UserAccountController
 * （src/api/userAccount.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询用户，支持新增/编辑/删除、角色分配（getUserRoles / assignRoles）、
 * 重置密码；搜索表单由静态字段（用户名/姓名/手机号/状态）与异步选项字段
 * （公司/部门/岗位，因选项需加载后才有，用自定义搜索区承载）组成。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { Badge, Button, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@ydsz-core/shadcn-ui';
import { ElMessageBox } from '@ydsz/notification/compat';
import { useI18n } from 'vue-i18n';
import { h, onMounted, reactive, ref } from 'vue';

import { createLogger } from '@ydsz-core/shared/utils';

const logger = createLogger('userinfo-user');
const { t } = useI18n();

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { list as companyList } from '#/api/company';
import type { CompanyVO } from '#/api/models';
import { tree as deptTree } from '#/api/department';
import type { DepartmentTreeVO } from '#/api/models';
import { list as postList } from '#/api/post';
import type { PostVO } from '#/api/models';
import { list as roleList } from '#/api/role';
import type { RoleVO } from '#/api/models';
import {
  downloadImportTemplate,
  exportUsers,
  getUserRoles,
  page,
  remove,
  resetPassword,
} from '#/api/userAccount';
import type { UserAccountVO } from '#/api/models';

import RoleAssign from './role-assign.vue';
import UserForm from './user-form.vue';
import UserImport from './user-import.vue';

defineOptions({ name: 'UserManagement' });

/** 判断用户状态是否启用（契约 status 为数字，1 启用 / 0 禁用） */
function isEnabled(status?: number): boolean {
  return status === 1;
}

// ========== 下拉选项数据（公司/部门/岗位/角色） ==========
const companyOptions = ref<CompanyVO[]>([]);
const deptTreeData = ref<DepartmentTreeVO[]>([]);
const postOptions = ref<PostVO[]>([]);
const roleOptions = ref<RoleVO[]>([]);

/** 部门 id -> 部门名称（树拍平） */
const deptNameMap = new Map<string, string>();
/** 岗位编码 -> 岗位名称（positionCode 与 postCode 对应） */
const postNameMap = new Map<string, string>();

function flattenDeptTree(nodes: DepartmentTreeVO[]) {
  nodes.forEach((node) => {
    if (node.id && node.deptName) {
      deptNameMap.set(node.id, node.deptName);
    }
    if (node.children?.length) {
      flattenDeptTree(node.children);
    }
  });
}

async function loadOptions() {
  try {
    const [companies, depts, posts, roles] = await Promise.all([
      companyList(),
      deptTree(),
      postList(),
      roleList(),
    ]);
    companyOptions.value = companies ?? [];
    deptTreeData.value = depts ?? [];
    postOptions.value = posts ?? [];
    roleOptions.value = roles ?? [];
    deptNameMap.clear();
    flattenDeptTree(deptTreeData.value);
    postNameMap.clear();
    postOptions.value.forEach((post) => {
      if (post.postCode && post.postName) {
        postNameMap.set(post.postCode, post.postName);
      }
    });
  } catch (error) {
    logger.warn('加载下拉选项失败: {}', error);
  }
}

onMounted(loadOptions);

/** 自定义搜索区状态（公司/部门/岗位，选项为异步数据无法进入 formOptions 快照） */
const searchForm = reactive({
  companyId: '',
  deptId: '',
  positionCode: '',
});

function handleSearch() {
  gridApi.query();
}

function handleReset() {
  Object.assign(searchForm, { companyId: '', deptId: '', positionCode: '' });
  gridApi.query();
}

const gridOptions: VxeTableGridOptions<UserAccountVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('page.rowIndex') },
    { field: 'username', title: t('page.username'), width: 120 },
    { field: 'realName', title: t('page.realName'), width: 100 },
    { field: 'phone', title: t('page.phone'), width: 130 },
    { field: 'email', title: t('page.email'), minWidth: 150 },
    {
      field: 'companyId',
      title: t('user.company'),
      width: 120,
      slots: {
        default: ({ row }) =>
          h(
            'span',
            null,
            companyOptions.value.find((c) => c.id === row.companyId)?.companyName || '-',
          ),
      },
    },
    {
      field: 'deptId',
      title: t('user.dept'),
      width: 120,
      slots: {
        default: ({ row }) => h('span', null, deptNameMap.get(row.deptId ?? '') || '-'),
      },
    },
    {
      field: 'positionCode',
      title: t('user.position'),
      width: 100,
      slots: {
        default: ({ row }) =>
          h('span', null, postNameMap.get(row.positionCode ?? '') || '-'),
      },
    },
    {
      field: 'status',
      title: t('page.status'),
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            Badge,
            { variant: enable ? 'default' : 'destructive', class: enable ? 'bg-green-500 text-white hover:bg-green-600' : 'text-xs' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    { field: 'lastLoginAt', title: t('page.lastLogin'), width: 160 },
    { field: 'createdAt', title: t('page.createTime'), width: 160 },
    {
      field: 'action',
      title: t('page.operation'),
      width: 260,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              Button,
              { size: 'sm', variant: 'link', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              Button,
              { size: 'sm', variant: 'link', class: 'border-yellow-500 text-yellow-600 dark:text-yellow-400', onClick: () => handleAssignRoles(row) },
              () => t('page.roleAssign'),
            ),
            h(
              Button,
              { size: 'sm', variant: 'ghost', onClick: () => handleResetPassword(row) },
              () => t('page.passwordReset'),
            ),
            h(
              Button,
              { size: 'sm', variant: 'link', class: 'text-destructive', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...searchForm, ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'Input',
        componentProps: { placeholder: t('page.username') },
        fieldName: 'username',
        label: t('page.username'),
      },
      {
        component: 'Input',
        componentProps: { placeholder: t('page.realName') },
        fieldName: 'realName',
        label: t('page.realName'),
      },
      {
        component: 'Input',
        componentProps: { placeholder: t('page.phone') },
        fieldName: 'phone',
        label: t('page.phone'),
      },
      {
        component: 'Select',
        componentProps: {
          placeholder: t('page.status'),
          options: [
            { label: t('page.enabled'), value: '1' },
            { label: t('page.disabled'), value: '0' },
          ],
        },
        fieldName: 'status',
        label: t('page.status'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 导入弹窗 ==========
const [UserImportModal, userImportApi] = useYDSZModal({ connectedComponent: UserImport });

// ========== 表单弹窗 ==========
const [UserFormModal, userFormApi] = useYDSZModal({ connectedComponent: UserForm });

function handleAdd() {
  userFormApi.setData({
    companyList: companyOptions.value,
    deptTreeData: deptTreeData.value,
    postList: postOptions.value,
    roleList: roleOptions.value,
  });
  userFormApi.open();
}

// ========== 导入导出 ==========
function handleImport() {
  userImportApi.open();
}

async function handleExport() {
  try {
    await exportUsers({});
    showToast.success(t('page.exportSuccess'));
  } catch (error) {
    logger.warn('导出用户失败: {}', error);
  }
}

async function handleDownloadTemplate() {
  try {
    await downloadImportTemplate({});
    showToast.success(t('page.templateDownloadSuccess'));
  } catch (error) {
    logger.warn('下载模板失败: {}', error);
  }
}

function handleEdit(row: UserAccountVO) {
  userFormApi.setData({
    record: row,
    companyList: companyOptions.value,
    deptTreeData: deptTreeData.value,
    postList: postOptions.value,
    roleList: roleOptions.value,
  });
  userFormApi.open();
}

// ========== 角色分配弹窗 ==========
const [RoleAssignModal, roleAssignApi] = useYDSZModal({ connectedComponent: RoleAssign });

async function handleAssignRoles(row: UserAccountVO) {
  if (!row.id) return;
  let selectedRoleIds: string[] = [];
  try {
    selectedRoleIds = (await getUserRoles({ userId: row.id })) ?? [];
  } catch (error) {
    logger.warn('获取用户角色失败: {}', error);
  }
  roleAssignApi.setData({
    userId: row.id,
    username: row.username,
    roleList: roleOptions.value,
    selectedRoleIds,
  });
  roleAssignApi.open();
}

// ========== 重置密码 ==========
async function handleResetPassword(row: UserAccountVO) {
  if (!row.id) return;
  let newPassword: string;
  // 步骤1：输入弹窗（用户取消直接返回）
  try {
    const { value } = await ElMessageBox.prompt(
      t('user.resetPasswordPrompt', { username: row.username ?? '' }),
      t('page.passwordReset'),
      {
        confirmButtonText: t('page.confirm'),
        cancelButtonText: t('page.cancel'),
        inputPattern: /.{6,}/,
        inputErrorMessage: t('user.passwordMinLength'),
      },
    );
    newPassword = value;
  } catch {
    // 用户主动取消重置密码
    return;
  }
  // 步骤2：执行重置密码 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await resetPassword({ userId: row.id, newPassword });
    showToast.success(t('page.passwordResetSuccess'));
  } catch (error) {
    logger.warn('重置密码失败: {}', error);
  }
}

// ========== 删除 ==========
async function handleDelete(row: UserAccountVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(
      t('user.deleteUserConfirm', { username: row.username ?? '' }),
      t('page.confirmDelete'),
      { type: 'warning' },
    );
  } catch {
    // 用户主动取消删除
    return;
  }
  // 步骤2：执行删除 API
  try {
    await remove({ id: row.id });
    showToast.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除用户失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <div class="flex flex-wrap items-center gap-2 px-4 pt-3">
      <span class="text-sm text-gray-500">{{ t('user.moreFilter') }}</span>
      <Select v-model="searchForm.companyId">
        <SelectTrigger class="w-44">
          <SelectValue :placeholder="t('user.company')" />
        </SelectTrigger>
        <SelectContent>
          <SelectItem
            v-for="item in companyOptions"
            :key="item.id"
            :value="item.id ?? ''"
          >
            {{ item.companyName }}
          </SelectItem>
        </SelectContent>
      </Select>
      <ElTreeSelect
        v-model="searchForm.deptId"
        :data="deptTreeData"
        :props="{ label: 'deptName', children: 'children' }"
        node-key="id"
        check-strictly
        :placeholder="t('user.dept')"
        clearable
        class="w-44"
      />
      <Select v-model="searchForm.positionCode">
        <SelectTrigger class="w-44">
          <SelectValue :placeholder="t('user.position')" />
        </SelectTrigger>
        <SelectContent>
          <SelectItem
            v-for="item in postOptions"
            :key="item.postCode"
            :value="item.postCode ?? ''"
          >
            {{ item.postName }}
          </SelectItem>
        </SelectContent>
      </Select>
      <Button variant="default" @click="handleSearch">{{ t('page.query') }}</Button>
      <Button variant="ghost" @click="handleReset">{{ t('page.reset') }}</Button>
    </div>
    <Grid :table-title="t('user.userManagement')">
      <template #toolbar-tools>
        <Button variant="default" @click="handleAdd">{{ t('user.createUser') }}</Button>
        <Button variant="outline" @click="handleImport">{{ t('user.importUser') }}</Button>
        <Button variant="secondary" @click="handleExport">{{ t('user.exportUser') }}</Button>
        <Button variant="ghost" @click="handleDownloadTemplate">{{ t('user.downloadTemplate') }}</Button>
      </template>
    </Grid>
    <UserFormModal @success="gridApi.query()" />
    <RoleAssignModal @success="gridApi.query()" />
    <UserImportModal @success="gridApi.query()" />
  </Page>
</template>